#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Skyclause pilot setup (#48). Run from a clean, up-to-date main: `bash pilot/wizard.sh`. Re-run it to re-mint the
# CI token after a revocation; stages already done are detected and skipped. Paths are from the repo root.

# The repo-root .env (gitignored), shared with pilot/workflows/ge-setup.sh (#49), so the owner's address, the alert
# emails and the conditions calendar carry over. It also keeps the IDs and the device tokens the owner hands out.
ENV_FILE=.env

REPO=m1kulabs/Skyclause
PROJECT=skyclause
PROJECT_NUMBER=413187272599
REPO_ID=1444328887
POOL=github
PROVIDER=skyclause-repo
WIF_PROVIDER="projects/$PROJECT_NUMBER/locations/global/workloadIdentityPools/$POOL/providers/$PROVIDER"
# This repo's OIDC subjects use the immutable form, so google.subject must be the raw `sub` claim (#89 binds to it).
WIF_CONDITION="assertion.repository_id == '$REPO_ID' && assertion.ref == 'refs/heads/main'"
REPO_PRINCIPALS="principalSet://iam.googleapis.com/projects/$PROJECT_NUMBER/locations/global/workloadIdentityPools/$POOL/attribute.repository_id/$REPO_ID"
BUCKET=skyclause-camera
CLASP_CLIENT_ID=1072944905499-vm2v2i5dvn0a0d2o4ca36i1vge8cvbn0.apps.googleusercontent.com
# The pilot's own project file, named apart from the .clasp.json each developer keeps for their dev script.
CLASP_PROJECT=pilot/apps-script/.clasp-pilot.json
# Besides GitHub's own; sorted, as the API returns them.
ALLOWED_ACTIONS=('google-github-actions/*' 'oven-sh/setup-bun@*' 'tailscale/github-action@*')
TOKENS=(CAMERA_TOKEN PI_TOKEN LABEL_TOKEN_A LABEL_TOKEN_B)

BUN_CACHE="${BUN_INSTALL_CACHE_DIR:-$HOME/.bun/install/cache}"

# pclasp runs clasp as the pilot owner: stage 3's login lives under a temporary HOME, so your ~/.clasprc.json is
# never read or overwritten.
pclasp() { HOME="$WIZ_TMP/home" BUN_INSTALL_CACHE_DIR="$BUN_CACHE" bunx @google/clasp@3.4.1 "$@"; }

# gh_var NAME prints a repository variable, or nothing if it's unset; a failed call fails, so it's never "unset".
gh_var() { gh variable list -R "$REPO" --json name,value --jq ".[] | select(.name == \"$1\") | .value"; }
# grep without -q reads all its input, so pipefail never sees gh die of SIGPIPE.
has_secret() { gh secret list -R "$REPO" --json name --jq '.[].name' 2>/dev/null | grep -x "$1" >/dev/null; }

health_json() { curl -fsSL "${INGEST_URL}?health=1" 2>/dev/null || true; }
# Anonymous on purpose: the camera phone and the Pi post without signing in.
health_ok() { [[ -n "${INGEST_URL:-}" ]] && health_json | jq -e '.ok == true' >/dev/null 2>&1; }

latest_dispatch() {
  gh run list -R "$REPO" --workflow "$1" --event workflow_dispatch -L 1 --json databaseId --jq '.[0].databaseId // empty' ||
    true
}

# stored NAME stops the run unless GitHub now holds $NAME, so a later stage never builds on a missing value.
stored() {
  [[ "$(gh_var "$1")" == "${!1}" ]] || { warn "GitHub doesn't hold $1 yet; fix gh, then re-run"; exit 1; }
}

already() {
  note "✓ already done: $1"
  pause
}

# clip VALUE copies VALUE to the clipboard, so a token is pasted and never shown on screen.
clip() {
  if command -v pbcopy >/dev/null 2>&1; then printf '%s' "$1" | pbcopy
  elif command -v wl-copy >/dev/null 2>&1; then printf '%s' "$1" | wl-copy
  elif command -v xclip >/dev/null 2>&1; then printf '%s' "$1" | xclip -selection clipboard
  elif command -v clip.exe >/dev/null 2>&1; then printf '%s' "$1" | clip.exe
  else return 1; fi
}

# property NAME VALUE walks one Script Property into the editor's Script Properties form.
property() {
  step "Add script property → Property: $1"
  if clip "$2"; then step "Value: paste it (it's on your clipboard)"; else step "Value: $2"; fi
  pause "Added?"
}

wif_done() {
  local enabled provider policy
  enabled=$(gcloud services list --enabled --project "$PROJECT" --format='value(config.name)' 2>/dev/null) || return 1
  for api in iam iamcredentials sts cloudresourcemanager; do grep -qx "$api.googleapis.com" <<<"$enabled" || return 1; done
  provider=$(gcloud iam workload-identity-pools providers describe "$PROVIDER" --workload-identity-pool="$POOL" \
    --location=global --project "$PROJECT" --format=json 2>/dev/null) || return 1
  jq -e --arg condition "$WIF_CONDITION" '.state == "ACTIVE" and .attributeCondition == $condition
    and .attributeMapping["google.subject"] == "assertion.sub"
    and .attributeMapping["attribute.repository_id"] == "assertion.repository_id"' <<<"$provider" >/dev/null || return 1
  gcloud storage buckets describe "gs://$BUCKET" --format=json 2>/dev/null |
    jq -e '.location == "ASIA-SOUTHEAST1" and .uniform_bucket_level_access == true' >/dev/null || return 1
  policy=$(gcloud storage buckets get-iam-policy "gs://$BUCKET" --format=json 2>/dev/null) || return 1
  jq -e --arg repo "$REPO_PRINCIPALS" '
    any(.bindings[]; .role == "roles/storage.objectViewer" and (.members | index("allUsers")))
    and any(.bindings[]; .role == "roles/storage.objectUser" and (.members | index($repo)))
    and any(.bindings[]; .role == "roles/storage.bucketViewer" and (.members | index($repo)))' <<<"$policy" >/dev/null || return 1
  [[ "$(gh_var GCP_PROJECT_ID)" == "$PROJECT" && "$(gh_var GCP_WIF_PROVIDER)" == "$WIF_PROVIDER" &&
    "$(gh_var CAMERA_BUCKET)" == "$BUCKET" ]]
}

wif_apply() {
  local oidc=(--location=global --workload-identity-pool="$POOL" --project "$PROJECT"
    --attribute-mapping='google.subject=assertion.sub,attribute.repository_id=assertion.repository_id'
    --attribute-condition="$WIF_CONDITION")
  gcloud services enable iam.googleapis.com iamcredentials.googleapis.com sts.googleapis.com \
    cloudresourcemanager.googleapis.com --project "$PROJECT"
  gcloud iam workload-identity-pools describe "$POOL" --location=global --project "$PROJECT" >/dev/null 2>&1 ||
    gcloud iam workload-identity-pools create "$POOL" --location=global --project "$PROJECT" --display-name='GitHub Actions'
  if gcloud iam workload-identity-pools providers describe "$PROVIDER" --workload-identity-pool="$POOL" \
    --location=global --project "$PROJECT" >/dev/null 2>&1; then
    gcloud iam workload-identity-pools providers update-oidc "$PROVIDER" "${oidc[@]}"
  else
    gcloud iam workload-identity-pools providers create-oidc "$PROVIDER" "${oidc[@]}" \
      --issuer-uri=https://token.actions.githubusercontent.com --display-name='m1kulabs/Skyclause main'
  fi
  gcloud storage buckets describe "gs://$BUCKET" >/dev/null 2>&1 ||
    gcloud storage buckets create "gs://$BUCKET" --project "$PROJECT" --location=asia-southeast1 --uniform-bucket-level-access
  gcloud storage buckets add-iam-policy-binding "gs://$BUCKET" --member=allUsers --role=roles/storage.objectViewer --format=none
  gcloud storage buckets add-iam-policy-binding "gs://$BUCKET" --member="$REPO_PRINCIPALS" --role=roles/storage.objectUser --format=none
  # rsync to a bucket root also reads the bucket's metadata (storage.buckets.get), which objectUser lacks.
  gcloud storage buckets add-iam-policy-binding "gs://$BUCKET" --member="$REPO_PRINCIPALS" --role=roles/storage.bucketViewer --format=none
  set_var GCP_PROJECT_ID "$PROJECT"
  set_var GCP_WIF_PROVIDER "$WIF_PROVIDER"
  set_var CAMERA_BUCKET "$BUCKET"
}

repo_settings_done() {
  local patterns
  patterns=$(IFS=,; printf '%s' "${ALLOWED_ACTIONS[*]}")
  gh api "repos/$REPO" --jq '.allow_squash_merge and (.allow_merge_commit | not) and (.allow_rebase_merge | not)
    and .squash_merge_commit_title == "PR_TITLE" and .squash_merge_commit_message == "COMMIT_MESSAGES"
    and .delete_branch_on_merge' | grep -x true >/dev/null &&
    gh api "repos/$REPO/vulnerability-alerts" --silent 2>/dev/null &&
    gh api "repos/$REPO/automated-security-fixes" --jq .enabled | grep -x true >/dev/null &&
    gh api "repos/$REPO/actions/permissions" --jq '.enabled and .allowed_actions == "selected" and .sha_pinning_required' |
    grep -x true >/dev/null &&
    gh api "repos/$REPO/actions/permissions/selected-actions" --jq ".github_owned_allowed and (.verified_allowed | not)
      and (.patterns_allowed | sort | join(\",\")) == \"$patterns\"" | grep -x true >/dev/null
}

# repo_setting "what" gh-api-args... applies one setting; GitHub Free answers 403 for some, which is recorded.
repo_setting() {
  local what="$1"; shift
  if gh api "$@" --silent; then note "✓ $what"; else SKIPPED+=("repo setting: $what (gh api $*)"); warn "GitHub refused: $what"; fi
}

repo_settings_apply() {
  repo_setting 'squash merges only, titled from the PR title; delete branches on merge' -X PATCH "repos/$REPO" \
    -F allow_squash_merge=true -F allow_merge_commit=false -F allow_rebase_merge=false \
    -f squash_merge_commit_title=PR_TITLE -f squash_merge_commit_message=COMMIT_MESSAGES -F delete_branch_on_merge=true
  repo_setting 'Dependabot alerts' -X PUT "repos/$REPO/vulnerability-alerts"
  repo_setting 'Dependabot security updates' -X PUT "repos/$REPO/automated-security-fixes"
  repo_setting 'actions allow-list, pinned by SHA' -X PUT "repos/$REPO/actions/permissions" \
    -F enabled=true -f allowed_actions=selected -F sha_pinning_required=true
  local patterns=()
  for action in "${ALLOWED_ACTIONS[@]}"; do patterns+=(-f "patterns_allowed[]=$action"); done
  repo_setting "allowed actions: GitHub's, ${ALLOWED_ACTIONS[*]}" -X PUT "repos/$REPO/actions/permissions/selected-actions" \
    -F github_owned_allowed=true -F verified_allowed=false "${patterns[@]}"
}

run_wizard() {

TOTAL_STAGES=9

cd "$(dirname "${BASH_SOURCE[0]}")/.."
WIZ_TMP=$(mktemp -d)
trap 'rm -rf "$WIZ_TMP" "$CLASP_PROJECT"' EXIT

for tool in git gh bun jq curl openssl gcloud; do
  command -v "$tool" >/dev/null 2>&1 || { warn "install $tool first, then re-run"; exit 1; }
done
gh auth status >/dev/null 2>&1 || { warn "run gh auth login first, then re-run"; exit 1; }

banner "Skyclause pilot setup"

stage "Pick the pilot owner"
say "One Google Workspace account owns the script, its triggers, the web app,"
say "the workbook, the calendars and the CI token. Consumer Gmail has no Workspace admin console for stage 2."
say "A Top 5 final needs the pilot's data reachable from the GE-licensed domain; #576 covers that step."
while true; do
  ask PILOT_OWNER_EMAIL "Pilot owner's Workspace email:"
  case "$PILOT_OWNER_EMAIL" in
    *@gmail.com | *@googlemail.com) warn "that's a consumer account; use the Workspace one" ;;
    ?*@?*.?*) break ;;
    *) warn "that isn't an email address" ;;
  esac
done
write_env PILOT_OWNER_EMAIL "$PILOT_OWNER_EMAIL"

# GitHub first; .env remembers an ID whose set_var failed, so a re-run never makes a second script or deployment.
PILOT_SCRIPT_ID=$(gh_var PILOT_SCRIPT_ID)
INGEST_DEPLOYMENT_ID=$(gh_var INGEST_DEPLOYMENT_ID)
INGEST_URL=$(gh_var INGEST_URL)
on_github=false
if [[ -n "$PILOT_SCRIPT_ID" && -n "$INGEST_DEPLOYMENT_ID" && -n "$INGEST_URL" ]]; then on_github=true; fi
[[ -n "$PILOT_SCRIPT_ID" ]] || PILOT_SCRIPT_ID=$(_existing PILOT_SCRIPT_ID || true)
[[ -n "$INGEST_DEPLOYMENT_ID" ]] || INGEST_DEPLOYMENT_ID=$(_existing INGEST_DEPLOYMENT_ID || true)
deployed_before=false
if [[ -n "$PILOT_SCRIPT_ID" && -n "$INGEST_DEPLOYMENT_ID" ]]; then deployed_before=true; fi

stage "Apps Script API and the admin checks"
# Once deployed these worked, but a token that dies after a while usually means Cloud session control.
if $deployed_before && ! confirm "The pilot is deployed. Walk through these checks again (after a red canary)?"; then
  note "✓ already done: the pilot web app is deployed"
else
  say "Signed in as $PILOT_OWNER_EMAIL:"
  open_url "https://script.google.com/home/usersettings"
  step "Turn on Google Apps Script API."
  pause "Done?"
  say "A Workspace admin checks three settings for the owner's organisational unit."
  open_url "https://admin.google.com/ac/owl"
  step "Manage App Access → Configure new app → search $CLASP_CLIENT_ID (clasp) → select it."
  step "Keep the scope on the owner's unit → Continue → Access to Google data: Trusted → Continue → Finish."
  pause "Done?"
  step "Menu → Security → Access and data control → Google Cloud session control."
  step "Either turn reauthentication off, or tick Exempt trusted apps. Else the CI token dies at the reauth interval."
  pause "Done?"
  step "Menu → Apps → Google Workspace → Drive and Docs → Sharing settings."
  step "Sharing outside the organisation: ON, so the web app can allow anyone, even anonymous (stage 5 checks it)."
  pause "Done?"
fi

stage "Mint the CI token (CLASPRC_JSON)"
if $deployed_before && has_secret CLASPRC_JSON &&
  ! confirm "CLASPRC_JSON is set. Mint a new one (after a revocation or a red canary)?"; then
  note "✓ kept the current CLASPRC_JSON"
else
  say "One clasp login as $PILOT_OWNER_EMAIL with clasp's own OAuth client, under a temporary HOME."
  step "In the browser, choose $PILOT_OWNER_EMAIL and allow every scope clasp asks for."
  mkdir -p "$WIZ_TMP/home"
  pclasp login
  login_email=$(pclasp --json show-authorized-user | jq -r '.email // empty')
  if [[ "$(tr '[:upper:]' '[:lower:]' <<<"$login_email")" != "$(tr '[:upper:]' '[:lower:]' <<<"$PILOT_OWNER_EMAIL")" ]]; then
    warn "signed in as ${login_email:-an unknown user}, not $PILOT_OWNER_EMAIL; re-run and choose the owner"
    exit 1
  fi
  clasprc=$(cat "$WIZ_TMP/home/.clasprc.json")
  skipped_before=${#SKIPPED[@]}
  set_secret CLASPRC_JSON "$clasprc"
  # The token lives only in this run's temporary HOME, so a failed write can't be finished by hand later.
  if (( ${#SKIPPED[@]} > skipped_before )); then warn "couldn't set CLASPRC_JSON; re-run to mint it again"; exit 1; fi
fi

stage "Create, push and deploy skyclause-pilot"
if $on_github; then
  already "script $PILOT_SCRIPT_ID, web app deployment $INGEST_DEPLOYMENT_ID"
else
  # An existing deployment is kept: its /exec URL may already be on the phone and the Pi.
  if [[ -z "$INGEST_DEPLOYMENT_ID" ]]; then
    git fetch -q origin main
    if ! git merge-base --is-ancestor HEAD origin/main || [[ -n "$(git status --porcelain -- pilot)" ]]; then
      warn "check out a commit on origin/main with no local changes under pilot/: CI's scope guard reads the manifest"
      warn "at the commit this stage deploys"
      exit 1
    fi
    if [[ -z "$PILOT_SCRIPT_ID" ]]; then
      mkdir -p "$WIZ_TMP/create"
      PILOT_SCRIPT_ID=$(cd "$WIZ_TMP/create" && pclasp --json create-script --type standalone --title skyclause-pilot |
        jq -r '.scriptId // empty')
      [[ -n "$PILOT_SCRIPT_ID" ]] || { warn "clasp created no script; see its output above"; exit 1; }
      write_env PILOT_SCRIPT_ID "$PILOT_SCRIPT_ID"
    fi
    printf '{"scriptId":"%s","rootDir":"dist"}\n' "$PILOT_SCRIPT_ID" > "$CLASP_PROJECT"
    PILOT_SCRIPT_ID="$PILOT_SCRIPT_ID" bun pilot/apps-script/build.ts
    pclasp -P "$CLASP_PROJECT" push --force
    INGEST_DEPLOYMENT_ID=$(pclasp -P "$CLASP_PROJECT" --json create-deployment -d "$(git rev-parse HEAD)" |
      jq -r '.deploymentId // empty')
    [[ -n "$INGEST_DEPLOYMENT_ID" ]] || { warn "clasp created no deployment; see its output above"; exit 1; }
    write_env INGEST_DEPLOYMENT_ID "$INGEST_DEPLOYMENT_ID"
  fi
  INGEST_URL="https://script.google.com/macros/s/$INGEST_DEPLOYMENT_ID/exec"
  write_env INGEST_URL "$INGEST_URL"
  set_var PILOT_SCRIPT_ID "$PILOT_SCRIPT_ID"
  set_var INGEST_DEPLOYMENT_ID "$INGEST_DEPLOYMENT_ID"
  set_var INGEST_URL "$INGEST_URL"
  stored PILOT_SCRIPT_ID
  stored INGEST_DEPLOYMENT_ID
  stored INGEST_URL
fi

stage "Run setup() for OAuth consent"
if health_ok; then
  note "✓ already done: health answers anonymously"
else
  open_url "https://script.google.com/d/$PILOT_SCRIPT_ID/edit"
  step "Signed in as $PILOT_OWNER_EMAIL: choose setup in the function list beside Debug, then Run."
  step "Review permissions → $PILOT_OWNER_EMAIL → if Google warns the app isn't verified: Advanced → Go to skyclause-pilot."
  step "Allow, then wait for the execution log's setup report: 26 tabs in each workbook."
  pause "Done?"
  until health_ok; do
    warn "health doesn't answer with ok: true yet: $(health_json | head -c 200)"
    note "No JSON at all means the Drive sharing setting from stage 2 still blocks anonymous access."
    pause "Fix it, then press Enter to check again"
  done
fi
health_json | jq . || true
pause

stage "Script Properties and device tokens"
if [[ -n "$(_existing SCRIPT_PROPERTIES_SET_ON || true)" ]] &&
  ! confirm "Script Properties were entered on $(_existing SCRIPT_PROPERTIES_SET_ON). Enter them again?"; then
  note "✓ kept the Script Properties"
else
  # Tokens already on a device stay: a token missing from .env may still be in the Script Properties.
  for name in "${TOKENS[@]}"; do
    if $deployed_before && [[ -z "$(_existing "$name" || true)" ]]; then
      warn "$name isn't in $ENV_FILE. Paste the one in the editor's Script Properties: a new token cuts off every device."
    fi
    ask_secret "$name" "$name: Enter keeps or generates it; paste it if the editor's Script Properties already hold one:"
    write_env "$name" "${!name:-$(openssl rand -hex 32)}"
  done
  ask TEAM_ALERT_EMAILS "Team alert emails, comma-separated (#57):"
  write_env TEAM_ALERT_EMAILS "$TEAM_ALERT_EMAILS"
  ask SEMESTER_ENDS_ON "APU's semester end, YYYY-MM-DD (#59; Enter to leave unset):" || true
  write_env SEMESTER_ENDS_ON "${SEMESTER_ENDS_ON:-}"
  ask CONDITIONS_CALENDAR_ID "Public conditions calendar ID from #49 (Enter to leave unset):" || true
  write_env CONDITIONS_CALENDAR_ID "${CONDITIONS_CALENDAR_ID:-}"
  open_url "https://script.google.com/d/$PILOT_SCRIPT_ID/edit"
  step "Project Settings (the gear) → Script Properties → Edit script properties."
  property PILOT_SCRIPT_ID "$PILOT_SCRIPT_ID"
  for name in "${TOKENS[@]}" TEAM_ALERT_EMAILS SEMESTER_ENDS_ON CONDITIONS_CALENDAR_ID; do
    if [[ -n "${!name}" ]]; then property "$name" "${!name}"; fi
  done
  step "Save script properties."
  pause "Saved?"
  write_env SCRIPT_PROPERTIES_SET_ON "$(date +%F)"
  note "Keep $ENV_FILE: the camera host pastes CAMERA_TOKEN on the phone (#60), the Pi gets PI_TOKEN (#68),"
  note "and the labelling links carry LABEL_TOKEN_A and LABEL_TOKEN_B (#61)."
  pause
fi

stage "Workload identity federation and the camera bucket"
if wif_done; then
  already "pool $POOL, provider $PROVIDER (repo $REPO_ID, refs/heads/main), gs://$BUCKET and the GitHub variables"
elif confirm "Create or fix them in project $PROJECT with your gcloud account ($(gcloud config get-value account 2>/dev/null))?"; then
  wif_apply
  pause
else
  SKIPPED+=("WIF and the camera bucket (re-run stage 7)")
fi

stage "Repository settings"
if repo_settings_done; then
  already "squash only from the PR title, branch deletion, Dependabot, and the SHA-pinned actions allow-list"
elif confirm "Apply squash-only merges, branch deletion, Dependabot and the SHA-pinned actions allow-list to $REPO?"; then
  repo_settings_apply
  pause
else
  SKIPPED+=("repo settings (re-run stage 8)")
fi

stage "Prove the deploy and the canary"
# DEPLOY_FREEZE is shared with P1's workflows and #78 owns it, so this stage only reads it.
workflows=(pilot-deploy.yml pilot-canary.yml)
freeze=$(gh_var DEPLOY_FREEZE)
if [[ "$freeze" == true ]]; then
  note "DEPLOY_FREEZE is true (#78), so only the canary runs; pilot-deploy waits for the freeze to lift."
  workflows=(pilot-canary.yml)
fi
if confirm "Dispatch ${workflows[*]} on main and watch them?"; then
  # The deploy first, so the canary checks what it deployed.
  for workflow in "${workflows[@]}"; do
    previous=$(latest_dispatch "$workflow")
    gh workflow run "$workflow" -R "$REPO" --ref main
    run_id=$previous
    for _ in $(seq 30); do
      [[ "$run_id" == "$previous" ]] || break
      sleep 2
      run_id=$(latest_dispatch "$workflow")
    done
    if [[ -z "$run_id" || "$run_id" == "$previous" ]]; then
      SKIPPED+=("find the $workflow run: gh run list -R $REPO --workflow $workflow")
      continue
    fi
    say "$workflow: https://github.com/$REPO/actions/runs/$run_id"
    gh run watch "$run_id" -R "$REPO" --exit-status ||
      SKIPPED+=("$workflow run $run_id failed: gh run view $run_id -R $REPO --log-failed")
    note "$workflow run $run_id finished: paste its ID on #48"
  done
  health_json | jq . || true
  pause
fi

finish
}

run_wizard "$@"; exit
